from render import render_rows
from totals import column_totals


def export_csv(rows, totals=False):
    if totals:
        # Render the original rows
        lines = render_rows(rows)
        # Compute totals row values
        totals_vals = column_totals(rows)
        # Create a row for totals: ["TOTAL"] + totals_vals
        totals_row = ["TOTAL"] + totals_vals
        # Render the totals row
        totals_line = render_rows([totals_row])[0]
        lines.append(totals_line)
        return "\n".join(lines)
    else:
        return "\n".join(render_rows(rows))

